) AS (
  VALUES 
    (158::BIGINT, 'Es muy buena profesora, recomiendo matricular con ella, explica de manera clara los temas, califica bien, es muy amable, le gusta mucho la participación en clase y te ayuda a corregir errores de escritura/pronunciación. Lo único es que, si hay que ir al día con ella, porque deja trabajos seguidos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-28T00:00:00+00:00'::TIMESTAMPTZ, '00396267164d3000ced8cf43b99e7da48e3b6a0d1dafc656453e29ade6f0b1de'::TEXT, ARRAY[547]::BIGINT[]),
    (158::BIGINT, 'La profe en general es buena, el problema es que ella si deja bastantes trabajos, exposiciones, tareas, siempre son super fáciles, pero si usted esta llevando muchos créditos le recomendaría otro profe que se la tire mas chill'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Muchos proyectos grupales']::TEXT[], '2026-06-04T00:00:00+00:00'::TIMESTAMPTZ, '39581d576fcb2a6bb02cd48fb11d4ceb8a307721a9c37e68dfa6c7e138800ec0'::TEXT, ARRAY[545]::BIGINT[]),
    (158::BIGINT, 'Mae si usted no es bueno en inglés no matricule con esta doñita. Baja puntos por cualquier vara, no es nada empática y siempre lo va a interrumpir mientras usted está hablando en inglés para corregirlo. Un verdadero dolor de huevos...'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2025-12-17T00:00:00+00:00'::TIMESTAMPTZ, '481c49a2ef8d2d65b4083eedd67cf26d21bda149b4b23ae14172e6113574901d'::TEXT, ARRAY[545]::BIGINT[]),
    (158::BIGINT, 'No califica tan duro, deja muchos trabajos y la mayoría son en grupo. Lo único es que realmente uno no aprende mucho de inglés, si hay alguien que realmente no sabe inglés y lleva el curso probablemente le vaya a costar un poco.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas']::TEXT[], '2025-12-05T00:00:00+00:00'::TIMESTAMPTZ, 'ba3aa9d626dca7bb1e63c1da8523b2c53718d642f8fec8386f41c65cc38d2618'::TEXT, ARRAY[545]::BIGINT[]),
    (158::BIGINT, 'si no se te dificulta inglés, te va a ir re bien, deja tareas normal, hace bastantes actividades interactivas, kahoot, hace trabajos grupales casi siempre'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos proyectos grupales']::TEXT[], '2025-06-28T00:00:00+00:00'::TIMESTAMPTZ, '1f857f215937920f4a5fe2f24d345f724d68644ee8cb8a69b0c5ebdf8f8ac0f8'::TEXT, ARRAY[625]::BIGINT[]),
    (158::BIGINT, 'Aquí no se viene a aprender, se viene a ser humillados por no saber lo que nunca se enseñó.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-03T00:00:00+00:00'::TIMESTAMPTZ, '14a552798c1c89cb5c288f5061fc9bcae45a7f989ccb222b19b6ed5f3e218ce3'::TEXT, ARRAY[539]::BIGINT[]),
    (158::BIGINT, 'Te humilla por no saber y calificar duro, no matricular por que si queda la gente en un curso que no vale la pena y deja mucha tarea clase siomifera'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2025-04-03T00:00:00+00:00'::TIMESTAMPTZ, 'a3eaf895a11009fbfd9378ad147fee84cc8e8c5d312b24e23bedf6368e23dfde'::TEXT, ARRAY[625]::BIGINT[]),
    (158::BIGINT, 'Sus clases son bien diseñadas y bastante claras. Mucho dinamismo y participación. Va al día con el Tec digital.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '4dc753c2767cf65f0fd48d474cc345f3f1b53e3e13045e07a8756354f0a2f50f'::TEXT, ARRAY[625]::BIGINT[]),
    (158::BIGINT, 'Es una profe que no está dispuesta a ayudar muchas veces, intenta tratarlo uno como inútil y las instrucciones no son claras.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2024-06-13T00:00:00+00:00'::TIMESTAMPTZ, '98154738fa0772fce68e812cc01c4260bc66174c81ccae2e75348853d5c1636e'::TEXT, ARRAY[625]::BIGINT[]),
    (158::BIGINT, 'El curso es demasiado fácil si ya tiene buenas bases de inglés, casi siempre sale temprano de las clases y algunas son virtuales.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-05-25T00:00:00+00:00'::TIMESTAMPTZ, 'e299dbed9d591ca613fb2f6df7d29ec5e26295689af9e9a8f22ecb7263d07b83'::TEXT, ARRAY[625]::BIGINT[]),
    (158::BIGINT, 'Si se le facilita el inglés, se pasa súper fácil el curso, es casi que la misma materia que Inglés I. La profe es muy linda y prioriza que le pongan atención, solo que los trabajos y rubros en ocasiones no eran muy claros. Es importante la asistencia.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2023-12-07T00:00:00+00:00'::TIMESTAMPTZ, '25437351a6c56d84400a75154623c3d8ddca893b00d858e9c1dd3cc956b99e4e'::TEXT, ARRAY[625]::BIGINT[]),
    (158::BIGINT, 'Las clases son semana presencial y semana virtual, durante todo el semestre. Le gusta que la gente participa, entre más se haga más rápido da por concluida la clase. Es un curso tranquilo si tienes una base o no te cuesta mucho. Todas las semanas hay cosas o tareas que hacer.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2023-11-26T00:00:00+00:00'::TIMESTAMPTZ, '8e701d0c97a979b8fdcd9497d8702a71e2a51e8ebc47bdd59a696ff8f44acc65'::TEXT, ARRAY[625]::BIGINT[]),
    (158::BIGINT, 'Está bien. Si tiene dificultades para inglés, entonces el curso puede ser difícil. En caso contrario, se pasa fácil.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa']::TEXT[], '2023-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'e82289a7680b2bdd2be8a80e109c6634fcc12b115e2e2f1ada8e57adc2488042'::TEXT, ARRAY[625]::BIGINT[]),
    (158::BIGINT, 'La profe es buena nota, sí le gusta que se le ponga atención y que participe. Además buscará cómo corregir a alguien si lo escucha pronunciar algo de manera incorrecta las veces que hagan falta. Es buena profe, pero casi que hay trabajos cada semana, fáciles, pero muchos'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos exámenes', 'Muchos proyectos grupales']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '2ea01c25ad22654ee2ba45889b4da2467f06001eae88cb7ffab606eb6bfdb90e'::TEXT, ARRAY[545]::BIGINT[]),
    (158::BIGINT, 'La profe es muy buena gente, da mucha retroalimentación en cuanto a pronunciación y hace bastantes actividades y trabajos en grupo durante y fuera de la clase, es muy buena profe y el curso se disfruta mucho, bastante recomendable'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-04T00:00:00+00:00'::TIMESTAMPTZ, 'db6700342c5155faea1b19305fa03c985f2a141d80d5e53d3b3792bce223b07e'::TEXT, ARRAY[545]::BIGINT[]),
    (158::BIGINT, 'La prfe es muy buena, las clases no son obligatorias pero la profe sí toma en cuenta la participación en clase, normalmente hay actividades en las clases.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes']::TEXT[], '2021-12-17T00:00:00+00:00'::TIMESTAMPTZ, 'b9f9773941a9dda4e872a67cc161c12b418614ba72e0c4cdee2f94e0ca36727a'::TEXT, ARRAY[625]::BIGINT[]),
    (158::BIGINT, 'Es muy buena, es seguro de que va pasar con buena nota solo que si de verdad quieres aprender estudie usted por su cuenta y no se vaya solo por el traductor Todas las semanas se entrega algo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, '176a7cfba0189596f6df0be58fcff28980674a0e76d227fa7ed5ccafccc334b7'::TEXT, ARRAY[545]::BIGINT[]),
    (158::BIGINT, 'La profe en si es muy buena , si usted tiene un nivel inglés medio o tiene muy buenas bases pasa el curso fácil . Si le cuesta el idioma es un poco más difícil pasar por que no hay mucho explicación pero los temas son súper básicos y sencillos . Todas las semanas hay algo que entregar .'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2021-07-28T00:00:00+00:00'::TIMESTAMPTZ, '7aac7447157098f57a20500bdbab938e52cc463625afd52cc179e81697728ecb'::TEXT, ARRAY[625]::BIGINT[]),
    (158::BIGINT, 'Deja una pequeña asignación cada semana no quita mucho tiempo y teniendo bases en el ingles es un curso llevadero'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa']::TEXT[], '2021-07-28T00:00:00+00:00'::TIMESTAMPTZ, 'ef68b39b6a67e59f31792929cbe7fb1505f74b2b2a0d9f14f3dabcf3eaa735cd'::TEXT, ARRAY[547]::BIGINT[]),
    (158::BIGINT, 'La profe es buena pero nunca atiende correos ni dudas, ella es amable y explica con cariño. Sus clases son aburridas pero ella se esfuerza por hacerlas mas amenas, no es mala profe pero tampoco es la mejor.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-23T00:00:00+00:00'::TIMESTAMPTZ, 'f24bf25c1398566250cee0293248aab7b22d5bf322d9b0b24cb55cc53d0719e5'::TEXT, ARRAY[545]::BIGINT[]),
    (158::BIGINT, 'Es bastante desordenada'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa']::TEXT[], '2021-07-06T00:00:00+00:00'::TIMESTAMPTZ, 'e21b54e6515cfd46db29cddc1913f1fee734b1308726fcd8c258bac1158fe242'::TEXT, ARRAY[539]::BIGINT[]),
    (158::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-03T00:00:00+00:00'::TIMESTAMPTZ, 'f202e6b35928c0db00c561ebe7f2b493ee7bd0d22de7e77fdec9b937132d4b0e'::TEXT, ARRAY[625]::BIGINT[]),
    (158::BIGINT, 'Un curso fácil si trae unas bases aceptables. No va aprender mucho, sin embargo, es una buena opción. Clases cortas, una pequeña asignación todas las semanas, pero no quita tiempo. Se la recomiendo si lo que quiere es salir del paso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, '04a860a0a090044f827139227ef5870e8ddd8709ffe82b9733a66fccb00dd10e'::TEXT, ARRAY[625]::BIGINT[]),
    (158::BIGINT, 'A mí se me hizo fácil porque tenía buenas bases, pero en realidad la explicación no es mucha, la mayoría de evaluaciones con más calificación son grupales pero no difíciles. Deja una pequeña evaluación semanal. La profesora es muy amable, eso sí'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'f91caee07b15c31f2399bb25b4181f2531b24620bd7fac04b41cb5d681a17032'::TEXT, ARRAY[547]::BIGINT[]),
    (158::BIGINT, 'Es la clase más fácil que llevé este semestre, todas las semanas hay una evaluación, pero no es difícil. Las clases son cortas, si hay muchos trabajos grupales que hacer, pero tampoco son difíciles. No es espere un super curso de ingles, solo concéntrese y prepárese. La profe es muy amable.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2021-06-17T00:00:00+00:00'::TIMESTAMPTZ, '3e1b53a53c99e931531925b84b2f662f373559425ca66c3d7ee7469c71986177'::TEXT, ARRAY[547]::BIGINT[]),
    (158::BIGINT, 'La profe sigue el cronograma correspondiente, hay actividades todas las semanas pero nada difícil. Le gusta que sea dinámico, mucha participación en clase, se trabaja en grupo tanto en clase como para proyectos. Por ser virtual pide muchos videos. A veces no corrige como debería.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2021-06-04T00:00:00+00:00'::TIMESTAMPTZ, 'f364ebc47d3dae5a7d12194413d6212c56cdd45e9f47b6cd9ae368b0dcbb1f43'::TEXT, ARRAY[547]::BIGINT[]),
    (158::BIGINT, 'Es buena profesora, a pesar de ser un poco desordenada, le gusta mucho que se trabaje en grupo, utiliza mucho las plataformas tecnológicas, los exámenes, quices, trabajos soy muy muy sencillos'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '6230e78ced9b504440ddde7f0e99b1f9bdbb685efa88c48dd209b054d1326058'::TEXT, ARRAY[539]::BIGINT[]),
    (158::BIGINT, 'Tannia es un amor, el curso es bastante fácil, las clases cortas e interactivas. Los trabajos también son fáciles y cortos, y en modalidad virtual usa muchas herramientas para hacer su clase dinámica.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-01T00:00:00+00:00'::TIMESTAMPTZ, '8b025040e0d95d657f5b8f1027f5d49c8a2d2be437e477a4b20cc34d74d80bb7'::TEXT, ARRAY[545]::BIGINT[]),
    (158::BIGINT, 'Escuche muy bien porque ella habla en español muy poco, el curso es sencillo y se explica muy bien. Para cuestiones orales trate de ensayar un poco antes porque baja puntos si tartamudea o divaga, aparte de eso todo perfecto.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'aebea256c45a8a15546058f0d818be36bb3afe9cc8f8d98b4fb3d47204296e66'::TEXT, ARRAY[545]::BIGINT[]),
    (158::BIGINT, 'Buena profe, las clases fueron cortas en este semestre virtual. Explica muy bien y los laboratorios que asigna son muy sencillos. La recomiendo.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Pocos exámenes', 'Clases excelentes']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'c47dea75f8d493020e46d9006462a025c565e5f9a23ae3505d075850c6275715'::TEXT, ARRAY[539]::BIGINT[]),
    (158::BIGINT, 'Utiliza herramientas tecnológicas que hacen que la clase sea dinámica. Me gusta las actividades grupales porque puedo hablar mas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-03T00:00:00+00:00'::TIMESTAMPTZ, 'a5bf72c02a36b7602774b50718c5c8b1026294c041ae6683fd2681b00be6b93f'::TEXT, ARRAY[539]::BIGINT[]),
    (158::BIGINT, 'La profe es esfuerza muchísimo por hacer las clases interactivas, y la verdad es que son muy entretenidas, siempre pregunta a sus estudiantes si entienden y está mu anuente a explicar los punto que no quedan claros, es sin duda una de las mejores profes del TEC, les recomiendo muchísimo su curso.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-03T00:00:00+00:00'::TIMESTAMPTZ, 'a8bb6249abbb635ed2d3f9693ce4f85f0cd013d96e8a7b67c17938b19fbdf524'::TEXT, ARRAY[545]::BIGINT[]),
    (158::BIGINT, 'Excelente profe, clases entretenidas y se esfuerza mucho en hacerlas interactivas. Hace diversas actividades. Manda pocos trabajos. Incluso en modalidad Virtual ha sido muy esforzada en sus clases. No duden en matricular con ella , Super buena la mejor'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-01T00:00:00+00:00'::TIMESTAMPTZ, '720fb41e7cfdd736c340c498ec6cbfbade4d0d7c948065075f70e81c643ba94c'::TEXT, ARRAY[545]::BIGINT[]),
    (158::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2020-07-20T00:00:00+00:00'::TIMESTAMPTZ, 'c16f0ae83f9a446fc6acc7cdec359b46ccb2c3f935e3e5e7f5befbd59ff32468'::TEXT, ARRAY[545]::BIGINT[]),
    (158::BIGINT, 'Clases super largas y aburridas. No explica nada, solo hace los ejercicios del libro. Cree que todos dominan el ingles y para quienes les cuesta más lo intimida. Tiene una personalidad extraña y califica duro.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2019-11-23T00:00:00+00:00'::TIMESTAMPTZ, '83cf524d1c305b84f5431257262a01bbbefc9a21f8187a5673e6b9153e970108'::TEXT, ARRAY[2432]::BIGINT[]),
    (158::BIGINT, 'La profe explica bastante bien. Sus clases son un toque largas y aburridas pero sí se aprende lo básico. La recomiendo.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2019-06-11T00:00:00+00:00'::TIMESTAMPTZ, '75f2f4d6848d92c65e95429da9d0140c4823c9890a713b7fbc99f03eb715c1bf'::TEXT, ARRAY[547]::BIGINT[]),
    (158::BIGINT, 'La profe es tuanis, pero la clase es aburrida y el ambiente incomodo, hay que hacer casi todo en parejas y oralmente, deja tarea cada Semana, es buena pero no es la mejor'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-02-25T00:00:00+00:00'::TIMESTAMPTZ, '3348462fb8d821768b1afa7f9c235545d669fbe9d57fa7eeab276772a3e78297'::TEXT, ARRAY[545]::BIGINT[]),
    (158::BIGINT, 'Con un humor muy amargo, cree que las personas dominan al 100% el idioma y hace evaluaciones poco interesantes. Clases largas y aburridas'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas']::TEXT[], '2019-02-11T00:00:00+00:00'::TIMESTAMPTZ, 'd25151aaa00ddc0784fc5b4def6198ed33128bf56b2db7f085e963e1acce3af4'::TEXT, ARRAY[545]::BIGINT[]),
    (158::BIGINT, 'Muy buena profe. Hace las clases fáciles e interesantes. Apoya a todos y califica relativamente suave. Muy comprensible, aunque pasa lista todas las clases. La recomiendo :D'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2018-12-11T00:00:00+00:00'::TIMESTAMPTZ, '2f919f9aeb9b60c539ad09c8eaa8c4a3e2f1bafdf2fc6114497446d253facaa0'::TEXT, ARRAY[541]::BIGINT[]),
    (158::BIGINT, 'Muy buena profesora, la clase es entretenida y le ayuda a perder el miedo a hablar'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Brinda apoyo']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, '4a1bb5ed75b9ca6cd3fca79c3ca442aaf518a55f49939225b1be428bc55efb9a'::TEXT, ARRAY[545]::BIGINT[]),
    (158::BIGINT, 'Buena para el curso, hace que las clases sean tuanis.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'ac978d7da9b1b4177c3644edea3e86ca052fc96f8c8d3ee42d975f009fe4961f'::TEXT, ARRAY[545]::BIGINT[]),
    (158::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'f77020220adcce1b8ed6fba05a976d595339df4c4ae347f3e3192b6b6b9ebc83'::TEXT, ARRAY[545]::BIGINT[]),
    (158::BIGINT, 'Piensa que todos manejan el idioma e intimida a los que les cuesta un poco, clase aburrida con diferentes actividades orales, pero exámenes faciles'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-20T00:00:00+00:00'::TIMESTAMPTZ, '8c7020aa1cc781a099007bb54df239fbc3c0ab715d390677ecc8fdc1007e2c20'::TEXT, ARRAY[545]::BIGINT[]),
    (158::BIGINT, 'Sin duda muy buena profe, no dude en matricular. Pocas tareas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-12T00:00:00+00:00'::TIMESTAMPTZ, '525f5224793df2e8e83e707ebc05f3365d5b3f2d24cb897f2a531d26df4de900'::TEXT, ARRAY[545]::BIGINT[]),
    (158::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'ef9bab273ea9bdcaccb7f5e2c0d749eff9a5b047235948e6d0a5cc86f810fdd2'::TEXT, ARRAY[545]::BIGINT[]),
    (158::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2018-06-07T00:00:00+00:00'::TIMESTAMPTZ, '0a6ed1c79c9f224fadfe33955581f7d7b342f660ab1fac41eb51d03c5cde4427'::TEXT, ARRAY[547]::BIGINT[]),
    (158::BIGINT, 'En todas las clases hay entregas. No es buena explicando. Cree que todos saben inglés y a los que le cuesta inglés o son tímidos los presiona mucho. Es buena persona. Le interesa mucho la participación en clase, incluso lo califica; hace apuntes de quien participa y quien no para la nota final.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa']::TEXT[], '2018-01-15T00:00:00+00:00'::TIMESTAMPTZ, 'c4096ad51e4db85e46e65d8c1b6d7c3ad40f8439de0426399ff2b9952e6ec5eb'::TEXT, ARRAY[547, 625, 545, 2379]::BIGINT[]),
    (158::BIGINT, 'La clase es demasiado aburrida, por lo menos es fácil (si usted se la juega con el inglés) y además la profe es buena nota.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-07-05T00:00:00+00:00'::TIMESTAMPTZ, '35987a9b7ddb8d1658c91865d001ecdde692154dd8e8b6077bb38f9526e53fb4'::TEXT, ARRAY[625]::BIGINT[]),
    (158::BIGINT, 'Realmente no explica en la clase, solo hace actividades, el ambiente de la clase no me gustó mucho, debería de cambiar un poco su actitud en clase y con los estudiantes, de ahi en fuera todo bien, buena gente, deja tareas todas las semanas pero muy sencillo'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas']::TEXT[], '2017-06-12T00:00:00+00:00'::TIMESTAMPTZ, '8472d9bc610d3036ad34e65a3b48bcd52e26232fa2918b7073d54211b84b88b7'::TEXT, ARRAY[3027]::BIGINT[]),
    (158::BIGINT, 'No explica la materia.La profe trata de hacer actividades para no aburrir la clase, pero realmente no ayudan mucho. Deja tareas fáciles todas las semanas. El ambiente en la clase realmente es incómodo, no tiene modo de decir las cosas.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-03-28T00:00:00+00:00'::TIMESTAMPTZ, 'abdd6333745e77d7f2ad215d7abc5d0396dacd56ab67a2ba8b293543058c3f1a'::TEXT, ARRAY[2432]::BIGINT[]),
    (158::BIGINT, 'Es buena gente y respetuosa, el curso fue muy sencillo.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-04T00:00:00+00:00'::TIMESTAMPTZ, '18d12f98d4c3bc9844297a18d1022763e92935c280d4ec6180237eb144524665'::TEXT, ARRAY[625]::BIGINT[]),
    (158::BIGINT, 'Es un curso muy fácil, solo hay que ir a las clases y hacer las tareas. Los exámenes son normales, muy básicos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-21T00:00:00+00:00'::TIMESTAMPTZ, '3d50ad9e2edc1e594bf1b61553dc377533f58bb2d7e4dfeeb7c78c4c09a3ced4'::TEXT, ARRAY[625]::BIGINT[]),
    (158::BIGINT, 'Muy buena profe, deja presentaciones y tareas de vez en cuando. Trata de enseñar con diferentes actividades para que la clase no sea aburrida, recomendada.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-26T00:00:00+00:00'::TIMESTAMPTZ, '4712491fdd699c785cd608b25fcfc89edb5e90169959324d911bdf6a7d86c5b9'::TEXT, ARRAY[1170]::BIGINT[]),
    (158::BIGINT, 'Deja tareas todas las semanas pero muy fáciles'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2015-07-19T00:00:00+00:00'::TIMESTAMPTZ, 'abf5bbff1988ad2e7fe450e3dad4c189bbe66d20dae880d580fe12f7fd19f874'::TEXT, ARRAY[1168]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
